#include <iostream>
using namespace std;

using ll = long long;

const int NMAX = 2100;
const int MAXBIT = 62;

ll n, t;
ll cb[NMAX][NMAX];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> t;

    if (t <= 0 || (t & (t - 1)) != 0) {
        cout << 0 << '\n';
        return 0;
    }

    int e = 0;
    while (t != 1) {
        t >>= 1;
        ++e;
    }

    for (int i = 0; i < MAXBIT; ++i) {
        cb[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            cb[i][j] = cb[i - 1][j - 1] + cb[i - 1][j];
        }
    }

    ll ans = 0;
    int x = 0;
    n += 2;
    ++e;

    for (int b = MAXBIT - 1; b >= 0; --b) {
        if (n & (1LL << b)) {
            if (e - x >= 0) {
                ans += cb[b][e - x];
            }
            ++x;
            if (x > e) break;
        }
    }

    if (e == 1) --ans;

    cout << ans << '\n';
    return 0;
}

